# 文件映射表 —— 包内路径 ⇄ 系统路径
#
# 这是【单一事实来源】：install.sh、uninstall.sh、sync.sh 都读它。
# 新增一个要纳管的配置文件，只改这里一行，三个脚本自动跟上。
#
# 格式： <包内相对路径>  <系统路径>       （~ 和 $HOME 都会被展开）
# 第三列 module 由分组注释决定，见每段开头的 #@module 标记。

#@module hypr
config/hypr/mykeys.lua                    ~/.config/hypr/mykeys.lua
config/hypr/config/binds.lua              ~/.config/hypr/config/binds.lua
config/hypr/config/variables.lua          ~/.config/hypr/config/variables.lua
config/hypr/config/workspaces.lua         ~/.config/hypr/config/workspaces.lua
# windowrules 也是被改过的 CachyOS 官方文件（同 binds/variables/workspaces）。
# 当初加它是为了企业微信（wine）的幽灵窗规则；wine 已于 2026-10-09 整套卸载、
# 那两条规则已删，现在只剩浮动窗居中等零星改动，见 config/hypr/patches/windowrules.lua.patch。
config/hypr/config/windowrules.lua        ~/.config/hypr/config/windowrules.lua
# misc 同上（第 5 个被改过的官方文件）。加它是为了关掉 Hyprland 内置壁纸，
# 消除开机时 wall*.png 一闪而过的那 1.5 秒，见 docs/02-hyprland.md。
config/hypr/config/misc.lua               ~/.config/hypr/config/misc.lua
# 录屏脚本（wl-screenrec 的开始/停止切换封装），配合 binds.lua 的 Super+Shift/Alt+R。
# （2026-10-10 前 mod_hypr 是硬编码 put，这一段每加一行 install.sh 都得另补一行 put；
#   现在走 put_module，和别的模块一样只改这里。check.sh 会核对每个模块都有 put_module。）
bin/hypr-screenrec                        ~/.local/bin/hypr-screenrec
# 剪贴板面板的包装脚本。⚠ 2026-10-09 起 SUPER+V 已改走 Walker（launcher 模块），它【当前没有键位在用】，
# 留着是为了回退：把 mykeys.lua 第 18 节的命令换回 noct-panel clipboard 即可。
# 用快捷键开的 noctalia 面板会在【某种没查清的状态下】约 1 秒自己关掉，而那个状态里
# 「指针在不在面板矩形内」是决定性变量。这个脚本开完面板把指针挪进去钉住、关掉后还原，
# 不判断当前是不是坏状态（坏状态下是解药，好状态下只是多挪一次指针）。见 docs/07 坑 10。
bin/noct-panel                            ~/.local/bin/noct-panel
# Dolphin 目录跳转（文件管理器里的 zi），配合 mykeys.lua 第 20 节的 ALT+Z。
# 弹 kitty 跑 zoxide query -i，选中的目录经 D-Bus 在已有 Dolphin 窗口里开新标签页。
# 依赖 zoxide + fzf + kitty（都在 packages.txt）。见 docs/02-hyprland.md。
bin/dolphin-jump                          ~/.local/bin/dolphin-jump

#@module term
config/kitty/kitty.conf                   ~/.config/kitty/kitty.conf
config/kitty/themes/noctalia.conf         ~/.config/kitty/themes/noctalia.conf
config/alacritty/alacritty.toml           ~/.config/alacritty/alacritty.toml
config/alacritty/themes/noctalia.toml     ~/.config/alacritty/themes/noctalia.toml
home/.zshrc                               ~/.zshrc
home/.p10k.zsh                            ~/.p10k.zsh

#@module nvim
config/nvim/init.lua                      ~/.config/nvim/init.lua
config/nvim/lazyvim.json                  ~/.config/nvim/lazyvim.json
config/nvim/lazy-lock.json                ~/.config/nvim/lazy-lock.json
config/nvim/stylua.toml                   ~/.config/nvim/stylua.toml
config/nvim/.neoconf.json                 ~/.config/nvim/.neoconf.json
config/nvim/lua/config/lazy.lua           ~/.config/nvim/lua/config/lazy.lua
config/nvim/lua/config/options.lua        ~/.config/nvim/lua/config/options.lua
config/nvim/lua/config/keymaps.lua        ~/.config/nvim/lua/config/keymaps.lua
config/nvim/lua/config/autocmds.lua       ~/.config/nvim/lua/config/autocmds.lua
# util/term.lua：终端体验补丁，由 config/autocmds.lua 的 require("util.term").setup() 拉起。
# 四件事：① term_label() —— 读 /proc 认出终端里【正在跑的程序】，tabby.lua 的顶栏、
# <leader>fb 的条目、<leader>tl 的列表��处共用这一份，避免各读各的再次出现
# 「图标和名字打架」（那正是 tabby 当初踩过的坑）；② <C-r>/<leader>tn 手动起名，
# 改的是 buffer 名本身所以 <leader>fb 里搜得到；③ 给非浮动终端窗口打 snacks_main，
# 否则在终端里选文件会落到别的窗口、把布局挤乱；④ 终端被文件顶出窗口时清掉
# toggleterm 的陈旧 window 引用，否则下次 Ctrl+/ 会反过来挤走你刚打开的文件。
# ★ 这是 lua/ 下第一个 config/ 与 plugins/ 之外的目录。漏掉这行则新机器上 nvim
#   启动即报 module 'util.term' not found —— autocmds.lua 无条件 require 它，
#   且 plugins/tabby.lua 也 require 它（顶栏的终端名会连带失效）。
config/nvim/lua/util/term.lua             ~/.config/nvim/lua/util/term.lua
config/nvim/lua/plugins/colorscheme.lua   ~/.config/nvim/lua/plugins/colorscheme.lua
config/nvim/lua/plugins/disabled.lua      ~/.config/nvim/lua/plugins/disabled.lua
# image.nvim：打开图片文件 + 给 molten 出图。走 processor = "magick_cli"，只要系统的
# imagemagick 包（在 packages.txt），不要 luarock；build = false 防 lazy 去跑 luarocks。
# 与 snacks.lua 里关掉的 snacks.image 二选一，不能同开。见 docs/04-neovim.md。
config/nvim/lua/plugins/image.lua         ~/.config/nvim/lua/plugins/image.lua
config/nvim/lua/plugins/lualine.lua       ~/.config/nvim/lua/plugins/lualine.lua
config/nvim/lua/plugins/mini.lua          ~/.config/nvim/lua/plugins/mini.lua
# molten：.py 里跑 Jupyter kernel、输出内联。★ 光有这个文件不够 ——
# 需要 python-pynvim + python-ipykernel（在 packages.txt），且首次装完要
# :UpdateRemotePlugins 再重启 nvim，否则 :Molten* 全是 E492。见 docs/04-neovim.md。
config/nvim/lua/plugins/molten.lua        ~/.config/nvim/lua/plugins/molten.lua
config/nvim/lua/plugins/no-neck-pain.lua  ~/.config/nvim/lua/plugins/no-neck-pain.lua
config/nvim/lua/plugins/render-markdown.lua ~/.config/nvim/lua/plugins/render-markdown.lua
config/nvim/lua/plugins/snacks.lua        ~/.config/nvim/lua/plugins/snacks.lua
# tabby：给 tab 起名 + 重画顶栏。三个 tab 里两个是终端，原生 tabline 全显示成
# term://…:zsh 分不清。配色只写高亮组名（跟 tokyonight transparent 走），
# 分隔符用圆头 / 对齐 lualine 的 bubbles。依赖 Nerd Font 图标。
config/nvim/lua/plugins/tabby.lua         ~/.config/nvim/lua/plugins/tabby.lua
config/nvim/lua/plugins/toggleterm.lua    ~/.config/nvim/lua/plugins/toggleterm.lua

#@module ui
config/noctalia/config.toml               ~/.config/noctalia/config.toml
state/noctalia/settings.toml              ~/.local/state/noctalia/settings.toml
config/uwsm/env                           ~/.config/uwsm/env
config/gtk-3.0/settings.ini               ~/.config/gtk-3.0/settings.ini
config/gtk-4.0/gtk.css                    ~/.config/gtk-4.0/gtk.css
config/gtk-4.0/noctalia.css               ~/.config/gtk-4.0/noctalia.css
# ★ qt6ct.conf 包里存的是 skel 原样（`/home/$USER/`），install.sh 会在目标机改写成真路径。
#   所以它在 sync.sh --check 里【永远显示不一致】，这是预期的 —— 不能 --pull 它，
#   否则 /home/david 被写死进包，换机器就废了。改它的其他项时手动编辑包内文件。
#   下面这行 #@nopull 让 sync.sh 在 pull/pack 时自动跳过它（2026-08-26 加，
#   在此之前只有上面这段注释靠人自觉，结果包里真的被写死过一次）。
#@nopull config/qt6ct/qt6ct.conf
config/qt6ct/qt6ct.conf                   ~/.config/qt6ct/qt6ct.conf
config/qt6ct/colors/noctalia.conf         ~/.config/qt6ct/colors/noctalia.conf
config/kdeglobals                         ~/.config/kdeglobals
config/btop/btop.conf                     ~/.config/btop/btop.conf
config/btop/themes/noctalia.theme         ~/.config/btop/themes/noctalia.theme
# 默认打开方式三件套：图片 → imv，音视频 → mpv。见 docs/05-theme-ui.md。
# imv-viewer.desktop 是自建条目（不是覆盖系统的 imv-dir.desktop），去掉了 NoDisplay
# 好让它出现在 dolphin 的「打开方式」里；mimeapps.list 指向的就是它。
config/mimeapps.list                      ~/.config/mimeapps.list
config/mpv/mpv.conf                       ~/.config/mpv/mpv.conf
share/applications/imv-viewer.desktop     ~/.local/share/applications/imv-viewer.desktop
# 启动器里的「Waydroid 重启」：Android 没网时点它（停会话再重开），见 docs/12 第 7 节。
share/applications/waydroid-restart.desktop  ~/.local/share/applications/waydroid-restart.desktop
# 启动器里的「Excalidraw」：点开时起 docker 容器、关窗口自动停，不用时零占用。
# 图标是从镜像里抠出来的 favicon.svg。见 docs/05-theme-ui.md「本地 Excalidraw 白板」。
bin/excalidraw                            ~/.local/bin/excalidraw
share/applications/excalidraw.desktop     ~/.local/share/applications/excalidraw.desktop
share/icons/hicolor/scalable/apps/excalidraw.svg  ~/.local/share/icons/hicolor/scalable/apps/excalidraw.svg
config/fcitx5/profile                     ~/.config/fcitx5/profile
config/fcitx5/config                      ~/.config/fcitx5/config
config/fcitx5/conf/notifications.conf     ~/.config/fcitx5/conf/notifications.conf
config/fcitx5/conf/classicui.conf         ~/.config/fcitx5/conf/classicui.conf
config/fontconfig/fonts.conf              ~/.config/fontconfig/fonts.conf

# fcitx5 输入法主题（Tokyo Night）。PNG 由 .src/*.svg 经 .src/render.sh 生成，
# 不要直接改 PNG。theme.conf 的写法有坑，见 docs/05-theme-ui.md。
share/fcitx5/themes/tokyonight/theme.conf     ~/.local/share/fcitx5/themes/tokyonight/theme.conf
share/fcitx5/themes/tokyonight/panel.png      ~/.local/share/fcitx5/themes/tokyonight/panel.png
share/fcitx5/themes/tokyonight/highlight.png  ~/.local/share/fcitx5/themes/tokyonight/highlight.png
share/fcitx5/themes/tokyonight/prev.png       ~/.local/share/fcitx5/themes/tokyonight/prev.png
share/fcitx5/themes/tokyonight/next.png       ~/.local/share/fcitx5/themes/tokyonight/next.png
share/fcitx5/themes/tokyonight/arrow.png      ~/.local/share/fcitx5/themes/tokyonight/arrow.png
share/fcitx5/themes/tokyonight/radio.png      ~/.local/share/fcitx5/themes/tokyonight/radio.png

#@module cc
# Claude Code 的本机工具（2026-08-26 加）。三个入口：
#   ccw/ccs 多会话看板（纯文本）· ccp 宠物版 TUI（能就地代答选择题）· statusline.sh 上下文占比状态栏
# alias 定义在 home/.zshrc（term 模块）里，所以装了 term 没装 cc 会得到三个指向空文件的 alias。
# ★ statusline.sh 要靠 ~/.claude/settings.json 的 statusLine 段才生效，而那个文件含明文
#   token、永不入包（见文末排除段）。所以 install.sh 的 mod_cc 会用 jq 把那一段【合并】进
#   本机的 settings.json —— 只加键、不读 token。这行注释别删，否则下次会以为状态栏白装了。
claude/cc_common.py                       ~/.claude/cc_common.py
claude/cc-pet.py                          ~/.claude/cc-pet.py
claude/cc-watch.py                        ~/.claude/cc-watch.py
claude/statusline.sh                      ~/.claude/statusline.sh
# 测试：test-cc.py 是纯函数、随手可跑；三个 e2e 会起真 claude 会话并消耗 API 额度，
# 它们的价值在于把「按键序列为什么是这样」的实测过程固化下来，性质接近 docs。
claude/test-cc.py                         ~/.claude/test-cc.py
claude/e2e_answer.py                      ~/.claude/e2e_answer.py
claude/e2e_ui.py                          ~/.claude/e2e_ui.py
claude/pty_drive.py                       ~/.claude/pty_drive.py
claude/probe_multiq.py                    ~/.claude/probe_multiq.py

#@module wall
# ⚠ D-ASCII 成品（wallpaper/ascii/*，含 settings.toml 默认指向的 a1-紫调少女.png）
#   【不要往这里加】—— install.sh 的 mod_wall 已经有一个 for 循环把整个
#   wallpaper/ascii/ 铺到 ~/Pictures/Wallpapers/tokyonight/D-ASCII/，
#   再在 manifest 里列一遍就是同一个文件被 put 两次、还会多出一条 sync 追踪项。
#   加新成品只要把图丢进 wallpaper/ascii/，那个循环自动带上（它按 * 匹配，
#   不是 *.png —— c2 是 .jpg）。
#
# 备选壁纸：wallhaven kxwp96（3840x2160，主色 #040509）。2026-09-03~09-16 期间是
# 本机在用的那张，现已跟远程切回 a1（主色 #1a1b26）。它不属于 tokyonight 色系库、
# 就是一张单独挑的图，所以放库根而不是 tokyonight/ 下，也就走 manifest 而非上面
# 那个循环。换回它的话 config/hypr/config/misc.lua 的 background_color 要重新采样，
# 命令见坑 15。
wallpaper/wallhaven-kxwp96.jpg            ~/Pictures/Wallpapers/wallhaven-kxwp96.jpg
wallpaper/tokyonight/_fetch.py            ~/Pictures/Wallpapers/tokyonight/_fetch.py
wallpaper/tokyonight/_fetch2.py           ~/Pictures/Wallpapers/tokyonight/_fetch2.py
wallpaper/tokyonight/_build.py            ~/Pictures/Wallpapers/tokyonight/_build.py
wallpaper/tokyonight/_ascii.py            ~/Pictures/Wallpapers/tokyonight/_ascii.py
wallpaper/tokyonight/_picks.json          ~/Pictures/Wallpapers/tokyonight/_picks.json
wallpaper/tokyonight/_picks2.json         ~/Pictures/Wallpapers/tokyonight/_picks2.json
wallpaper/tokyonight/index.html           ~/Pictures/Wallpapers/tokyonight/index.html

#@module ocr
# 屏幕取字。RapidOCR（PP-OCRv6 + onnxruntime）替代 normcap —— 后者底层是 Tesseract，
# 对屏幕小号中文粘连、漏字。模型加载（约 0.8s）抽进常驻服务，按键路径上只剩推理。
# 键位是 SUPER+SHIFT/ALT + O，写在 config/hypr/mykeys.lua 第 15 节（属 hypr 模块）。
# ★ 本仓库【第一个】带 systemd 单元的模块。put 只负责拷文件，install.sh 的 mod_ocr
#   里必须另有 daemon-reload + enable --now ocrd.socket，否则拷过去也不会被激活。
# ⚠ 运行时依赖 AUR 的 python-rapidocr，那个包要【本地改 PKGBUILD 才能装】，
#   并且已被 IgnorePkg 锁更新。整套缘由和重装步骤见 docs/10-ocr.md。
bin/ocr-server                            ~/.local/bin/ocr-server
bin/ocr-grab                              ~/.local/bin/ocr-grab
bin/theme-switch                          ~/.local/bin/theme-switch
bin/theme-preview                         ~/.local/bin/theme-preview
config/systemd/user/ocrd.socket           ~/.config/systemd/user/ocrd.socket
config/systemd/user/ocrd.service          ~/.config/systemd/user/ocrd.service

#@module launcher
# 应用启动器 Walker（GTK4 前端）+ Elephant（数据后端），2026-10-09 替换 noctalia 自带启动器。
# 键位 ALT+Space / SUPER+. 和 noctalia 顶栏按钮的接线在 hypr、ui 模块里，见 docs/13-launcher.md。
# ★ 同 ocr：两个 systemd 单元 put 完必须 daemon-reload + enable --now，install.sh 的
#   mod_launcher 里有；不 enable 的话 ALT+Space 拉起的是一个查不到任何东西的空 Walker。
# ⚠ 二进制全是 AUR 源码包，且 elephant 本体与所有 elephant-* 插件必须【同一次、同一个 Go
#   工具链】编出来（插件是 Go plugin，ABI 不对就加载失败），别混装 elephant-bin。
config/walker/config.toml                 ~/.config/walker/config.toml
config/walker/themes/noctalia/style.css   ~/.config/walker/themes/noctalia/style.css
config/walker/themes/noctalia/layout.xml  ~/.config/walker/themes/noctalia/layout.xml
config/elephant/websearch.toml            ~/.config/elephant/websearch.toml
config/elephant/windows.toml              ~/.config/elephant/windows.toml
# 同一个应用「有窗口→窗口排第一」：window_integration + 屏蔽 Waydroid 的同名副本，见 docs/13 坑 7。
config/elephant/desktopapplications.toml  ~/.config/elephant/desktopapplications.toml
# 剪贴板（SUPER+V，2026-10-09 起替代 noctalia 剪贴板面板）。clip-paste = 复制 + 自动粘贴，
# 由 clipboard.toml 的 command 用 $HOME 绝对路径调用（elephant 是 systemd 服务，PATH 无 ~/.local/bin）。
config/elephant/clipboard.toml            ~/.config/elephant/clipboard.toml
bin/clip-paste                            ~/.local/bin/clip-paste
config/systemd/user/elephant.service      ~/.config/systemd/user/elephant.service
config/systemd/user/walker.service        ~/.config/systemd/user/walker.service

# ── 不在同步范围内（有意）────────────────────────────────────────────────
# wallpaper/ascii/*.png                    _ascii.py 的产出，确定性生成，不会自己变。
#                                          由 install.sh 的 wall 模块直接铺开。
# state/noctalia/community-palettes/*      安装时才拷，路径含 URL 编码
# wallpaper/11-w55gjr.png                  壁纸本体，不会自己变
# config/nvim/lua/plugins/example.lua      LazyVim 自带样例，从不改
# share/fcitx5/themes/tokyonight/.src/     SVG 源与 render.sh，只在包里，不装到系统
# docs/img/*.png                           文档配图，同上
# bin/theme-switch                         主题循环切换脚本（Super+Shift+T 触发）
# bin/theme-preview                        当前主题片单即时翻墙纸（Super+I）
# ~/.ssh ~/.gnupg ~/.claude/settings.json  含密钥，永不入包
# ~/.local/share/fcitx5/rime/              个人词库，体积不定
